import csv

with open('outputs/t11_city_indicator_matrix.csv', 'r', newline='') as f:
    reader = csv.reader(f)
    for i, row in enumerate(reader):
        if i < 3:
            print(f'Row {i}: {len(row)} fields')
            for j, val in enumerate(row[:5]):
                print(f'  Col {j}: {repr(val)}')
        if i == 4:
            print(f'Row {i}: {len(row)} fields')
            for j, val in enumerate(row[:5]):
                print(f'  Col {j}: {repr(val)}')
            break
"
"}

